def minRectangleArea(matrix, target):
    R, C = len(matrix), len(matrix[0])
    best = 0
    for top in range(R):
        col = [0] * C
        for bottom in range(top, R):
            row = matrix[bottom]
            for c in range(C):
                col[c] += row[c]
            h = bottom - top + 1
            left = 0
            s = 0
            for right in range(C):
                s += col[right]
                while s >= target and left <= right:
                    area = h * (right - left + 1)
                    if best == 0 or area < best:
                        best = area
                    s -= col[left]
                    left += 1
    return best
